            if g[r][c]!=bg and not seen[r][c]:
                q=deque([(r,c)]); seen[r][c]=True; comp=[]
                while q:
                    x,y=q.popleft(); comp.append((x,y))
                    for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
                        nx,ny=x+dx,y+dy
                        if 0<=nx<H and 0<=ny<W and not seen[nx][ny] and g[nx][ny]==g[r][c]:
