def solve(g):
    H=len(g);W=len(g[0]);bg=C2(v for row in g for v in row).most_common(1)[0][0]
    stay=[[False]*W for _ in range(H)]
    for c in range(W): stay[H-1][c]=(g[H-1][c]!=bg)
    for r in range(H-2,-1,-1):
        for c in range(W):
            if g[r][c]!=bg and (r+1==H-1 or stay[r+1][c]): stay[r][c]=True
    out=[[bg]*W for _ in range(H)]
    for r in range(H):
        for c in range(W):
            v=g[r][c]
            if v==bg: continue
            if stay[r][c]: out[r][c]=v
            elif c+1<W: out[r][c+1]=v
    return out
