def f(g):
    H=len(g);W=max(map(len,g))
    bg=Counter(x for row in g for x in row).most_common(1)[0][0]
    cs=comps(g,bg)
    bycolor=dd(list)
    for v,cl in cs: bycolor[v].append(cl)
    keep={}
    for v,cls in bycolor.items():
        for cl in cls:
            # does cl touch any other same-color object (chebyshev adj)?
            touched=False
            for oth in cls:
                if oth==cl: continue
                for r,c in cl:
                    for dr in (-1,0,1):
                        for dc in (-1,0,1):
                            if (r+dr,c+dc) in oth: touched=True
            if touched: keep.setdefault(v,set()).update(cl)
            else:
                for r,c in {(r,c+1) for r,c in cl}: keep.setdefault(v,set()).add((r,c))
    out=[[g[r][c] for c in range(W)] for r in range(H)]
    for v,cells in keep.items():
        for r,c in cells: out[r][c]=v
    return out
