def feats(i,o):
    H,W=len(i),len(i[0])
    bg=Counter(x for row in i for x in row).most_common(1)[0][0]
    OH,OW=len(o),max(map(len,o))
    outset={(r,c) for r in range(OH) for c in range(OW) if o[r][c]!=bg}
    info={}
    for r in range(H):
        for c in range(W):
            v=i[r][c]
            if v==bg: continue
            info[(r,c)]={
                'v':v,'L':i[r][c-1] if c>0 else bg,'R':i[r][c+1] if c+1<W else bg,
                'U':i[r-1][c] if r>0 else bg,'D':i[r+1][c] if r+1<H else bg,
                'new_occ':(r,c) in outset,'new_pos':outset.contains((r,c+1) if False else None)
            }
    return bg,info,outset

