def try_rule(i,o,priority='free',order='scandir'):
    # cells marked to move: left neighbor == bg
    H=len(i);W=len(i[0]); OH=len(o); OW=max(map(len,o)); bg=Counter(x for row in i for x in row).most_common(1)[0][0]
    mark={(r,c) for r in range(H) for c in range(W) if i[r][c]!=bg and (c==0 or i[r][c-1]==bg)}
    # destinations of moved cells
    go=defaultdict(list)
    for r,c in mark: go[(r,c+1)].append(i[r][c])
    result=[[bg]*OW for _ in range(OH)]
    for r in range(OH):
        for c in range(OW):
            if go[c]>0 and priority=='first':
                v=go[c][0]
            elif priority=='last':
                v=go[c][-1]
            else:
                cnt=defaultdict(int)
                for v in go[c]: cnt[v]+=1
                v=max(cnt,key=cnt.get)
            result[r][c]=v
    return sum(1 for r in range(OH) for c in range(OW) if result[r][c]!=o[r][c])
for pri in ('last','first','maxcount','mincount'):
